package run.ikaros.notes; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PrivateNotesService{private final PrivateVaultRepository vaults;private final PrivateNotebookRepository notebooks;private final PrivateNoteRepository notes;public PrivateNotesService(PrivateVaultRepository v,PrivateNotebookRepository n,PrivateNoteRepository p){vaults=v;notebooks=n;notes=p;}public Mono<VaultView> createVault(UUID a,CreateVaultRequest q){Instant n=Instant.now();return vaults.save(new PrivateVaultEntity(null,a,q.name().trim(),"USER_LOCKED_E2EE",q.cryptoContext(),q.encryptedRecoveryKey(),VaultStatus.LOCKED,n,n,null)).map(this::vault);}public Flux<VaultView> vaults(UUID a){return vaults.findAllByOwnerIdOrderByCreatedAtDesc(a).map(this::vault);}public Mono<VaultView> lock(UUID a,UUID id){return ownVault(a,id).flatMap(v->vaults.save(new PrivateVaultEntity(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),v.encryptedRecoveryKey(),VaultStatus.LOCKED,v.createdAt(),Instant.now(),v.version()))).map(this::vault);}public Mono<VaultView> unlock(UUID a,UUID id){return ownVault(a,id).flatMap(v->vaults.save(new PrivateVaultEntity(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),v.encryptedRecoveryKey(),VaultStatus.UNLOCKED,v.createdAt(),Instant.now(),v.version()))).map(this::vault);}public Mono<NotebookView> createNotebook(UUID a,UUID v,CreateNotebookRequest q){return ownVault(a,v).flatMap(x->notebooks.save(new PrivateNotebookEntity(null,v,a,q.parentId(),q.encryptedName(),Instant.now(),Instant.now(),null))).map(this::notebook);}public Flux<NotebookView> notebooks(UUID a,UUID v){return ownVault(a,v).flatMapMany(x->notebooks.findAllByVaultIdAndOwnerIdOrderByCreatedAtAsc(v,a).map(this::notebook));}public Mono<NoteView> createNote(UUID a,UUID v,UpsertNoteRequest q){return ownVault(a,v).flatMap(x->notes.save(new PrivateNoteEntity(null,v,q.notebookId(),a,q.encryptedTitle(),q.encryptedBody(),q.encryptedProperties(),1,false,Instant.now(),Instant.now(),null))).map(this::note);}public Flux<NoteView> notes(UUID a,UUID v){return ownVault(a,v).flatMapMany(x->notes.findAllByVaultIdAndOwnerIdAndTombstoneFalseOrderByUpdatedAtDesc(v,a).map(this::note));}public Mono<NoteView> updateNote(UUID a,UUID id,UpsertNoteRequest q){return notes.findById(id).filter(n->n.ownerId().equals(a)&&!n.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Private Note 不存在或无权访问"))).flatMap(n->{if(n.revision()!=q.expectedRevision())return Mono.error(new ConflictException("Private Note Revision 冲突"));return notes.save(new PrivateNoteEntity(n.id(),n.vaultId(),q.notebookId(),n.ownerId(),q.encryptedTitle(),q.encryptedBody(),q.encryptedProperties(),n.revision()+1,false,n.createdAt(),Instant.now(),n.version()));}).map(this::note);}public Mono<NoteView> deleteNote(UUID a,UUID id){return notes.findById(id).filter(n->n.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Private Note 不存在或无权访问"))).flatMap(n->notes.save(new PrivateNoteEntity(n.id(),n.vaultId(),n.notebookId(),n.ownerId(),n.encryptedTitle(),n.encryptedBody(),n.encryptedProperties(),n.revision()+1,true,n.createdAt(),Instant.now(),n.version()))).map(this::note);}private Mono<PrivateVaultEntity> ownVault(UUID a,UUID id){return vaults.findById(id).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Private Vault 不存在或无权访问")));}private VaultView vault(PrivateVaultEntity v){return new VaultView(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),v.status(),v.createdAt());}private NotebookView notebook(PrivateNotebookEntity n){return new NotebookView(n.id(),n.vaultId(),n.parentId(),n.encryptedName(),n.createdAt());}private NoteView note(PrivateNoteEntity n){return new NoteView(n.id(),n.vaultId(),n.notebookId(),n.encryptedTitle(),n.encryptedBody(),n.encryptedProperties(),n.revision(),n.tombstone(),n.createdAt(),n.updatedAt());}}
